from __future__ import annotations

import os
import shutil
import stat
from typing import Dict, Optional, Tuple

__all__ = [
    \\\"join\\\",
    \\\"path_key\\\",
    \\\"list_entries\\\",
    \\\"stat_signature\\\",
    \\\"files_equal\\\",
    \\\"is_readonly\\\",
    \\\"make_writable\\\",
    \\\"remove_file\\\",
    \\\"remove_tree\\\",
    \\\"clear_path\\\",
    \\\"copy_file\\\",
    \\\"prune_empty_dirs\\\",
]


def join(root: str, relpath: str) -> str:
    \\\"\\\"\\\"把目标根目录和一个相对路径拼成绝对路径。\\\"\\\"\\\"
    return os.path.join(root, relpath)


def path_key(relpath: str) -> str:
    \\\"\\\"\\\"把相对路径规整成用于比较的键。

    目标平台的文件系统如何认定"两个路径写的是同一个东西"，由本函数
    决定；调用方不应自己再做字符串拼比较。
    \\\"\\\"\\\"
    normalized = relpath.replace(\\\"/\\\", os.sep)
    if os.name == \\\"nt\\\":
        normalized = normalized.lower()
    return normalized


def list_entries(root: str) -> Dict[str, str]:
    \\\"\\\"\\\"列出目录树中的所有普通文件。

    返回 \\\"\\\"{{相对路径: 绝对路径}}\\\"\\\"；\\\"\\\"root\\\"\\\" 不存在时返回空字典。
    \\\"\\\"\\\"
    entries: Dict[str, str] = {{}}
    if not os.path.isdir(root):
        return entries
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            relpath = os.path.relpath(full, root)
            entries[relpath] = full
    return entries


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    \\\"\\\"\\\"返回用于"内容是否变化"判定的签名。

    签名由大小与修改时间共同构成；读取失败时返回 \\\"\\\"None\\\"\\\"。
    \\\"\\\"\\\"
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def files_equal(path1: str, path2: str) -> bool:
    \\\"\\\"\\\"比较两个文件的内容是否完全一致。\\\"\\\"\\\"
    try:
        stat1 = os.stat(path1)
        stat2 = os.stat(path2)
        if stat1.st_size != stat2.st_size:
            return False
        chunk_size = 1024 * 1024
        with open(path1, \\\"rb\\\") as f1, open(path2, \\\"rb\\\") as f2:
            while True:
                chunk1 = f1.read(chunk_size)
                chunk2 = f2.read(chunk_size)
                if chunk1 != chunk2:
                    return False
                if not chunk1:
                    return True
    except OSError:
        return False


def is_readonly(path: str) -> bool:
    \\\"\\\"\\\"路径是否带有只读属性。\\\"\\\"\\\"
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def make_writable(path: str) -> None:
    \\\"\\\"\\\"去掉路径的只读属性。\\\"\\\"\\\"
    try:
        current_mode = os.stat(path).st_mode
        os.chmod(path, current_mode | stat.S_IWRITE)
    except OSError:
        pass


def remove_file(path: str) -> None:
    \\\"\\\"\\\"删除单个文件，必要时先去掉只读属性。\\\"\\\"\\\"
    if is_readonly(path):
        make_writable(path)
    os.remove(path)


def remove_tree(path: str) -> None:
    \\\"\\\"\\\"递归删除一棵目录树，必要时先去掉只读属性。\\\"\\\"\\\"
    def handle_remove_readonly(func, path, exc):
        \\\"\\\"\\\"处理 shutil.rmtree 的只读错误。\\\"\\\"\\\"
        if is_readonly(path):
            make_writable(path)
            func(path)
        else:
            raise
    shutil.rmtree(path, onerror=handle_remove_readonly)


def clear_path(path: str) -> None:
    \\\"\\\"\\\"清理路径上的任何内容（文件或目录）。

    如果路径是文件则删除文件，如果是目录则递归删除整棵树。
    路径不存在时什么也不做。
    \\\"\\\"\\\"
    if not os.path.exists(path):
        return
    if os.path.isfile(path):
        remove_file(path)
    elif os.path.isdir(path):
        remove_tree(path)


def copy_file(source: str, target: str) -> None:
    \\\"\\\"\\\"把 \\\"\\\"source\\\"\\\" 的内容写到 \\\"\\\"target\\\"\\\"，必要时创建父目录，并保留源的修改时间。\\\"\\\"\\\"
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)
    if os.path.exists(target) and is_readonly(target):
        make_writable(target)
    with open(source, \\\"rb\\\") as src_handle, open(target, \\\"wb\\\") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)
    try:
        stat_info = os.stat(source)
        os.utime(target, (stat_info.st_atime, stat_info.st_mtime))
    except OSError:
        pass


def prune_empty_dirs(root: str) -> None:
    \\\"\\\"\\\"自底向上删除目标树中的空目录（不含 \\\"\\\"root\\\"\\\" 自身）。\\\"\\\"\\\"
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                if is_readonly(dirpath):
                    make_writable(dirpath)
                os.rmdir(dirpath)
        except OSError:
            pass
